CREATE TABLE "badges" (
  "Id" INTEGER,
  "UserId" INTEGER,
  "Name" TEXT,
  "Date" DATETIME
);

CREATE TABLE "CommentDetails" (
  "Id" INTEGER,
  "Score" INTEGER,
  "Text" TEXT,
  "CreationDate" DATETIME
);

CREATE TABLE "CommentRelations" (
  "Id" INTEGER,
  "PostId" INTEGER,
  "UserId" INTEGER,
  "UserDisplayName" TEXT
);
